#!/usr/bin/env bash
# GENERATED by git-policy-install from the machine's git-control config on
# 2026-11-18. Regenerate (git-policy-install --force) after policy changes;
# do not hand-edit: two sources of the same policy is the one that rots.
#
# The server-side projection of the local policy: the hosting builds
# squash-merge commits from the PR title and body, so no local hook ever
# sees the message that lands on the default branch. This guard validates
# exactly that message, and every commit the PR carries, and its failure
# output carries the repair recipe.
set -euo pipefail

pr="${1:?pr number required}"
repo="${GITHUB_REPOSITORY:?GITHUB_REPOSITORY required}"
base_url="${FORGEJO_URL:-}"
token="${FORGEJO_TOKEN:-}"

types='feat|fix|docs|refactor|perf|test|build|ci|chore|release|evidence|cert'
agent_terms='claude|anthropic|codex|openai|mcode|opencode|zcode|copilot|gemini|aider|cody|pi'
allowed_emails='^(ilargia\.c\.g@gmail\.com|haizea\.cabrera\.g@gmail\.com|pabloformacion13@gmail\.com|rubentxu74@gmail\.com|socketstuido@gmail\.com|nomeacuerdodelputocorreo@gmail\.com|rubentxudev@gmail\.com|rdcabrerag@eservicios\.indra\.es|Rubentxu@users\.noreply\.github\.com|noreply@github\.com)$'
trailer_re='^\s*(co-authored-by|co-author)\s*:'
header_max=120

violations=0
say() { printf '%s\n' "$*" >&2; violations=$((violations + 1)); }
has_term() { printf '%s' "$1" | grep -iqE "\b($agent_terms)\b"; }

if [[ -n "$base_url" ]]; then
  gh_api() { curl -sfS -H "Authorization: token $token" "$base_url/api/v1/$1"; }
  pr_json="$(gh_api "repos/$repo/pulls/$pr")"
  commits_json="$(gh_api "repos/$repo/pulls/$pr/commits")"
else
  pr_json="$(gh api "repos/$repo/pulls/$pr")"
  commits_json="$(gh api "repos/$repo/pulls/$pr/commits" --paginate)"
fi
title="$(printf '%s' "$pr_json" | jq -r .title)"
body="$(printf '%s' "$pr_json" | jq -r '.body // ""')"

if has_term "$title"; then
  say "DENY MSG: the PR TITLE carries a blocked term; it becomes the squash header"
fi
if [ -n "$body" ] && has_term "$body"; then
  say "DENY MSG: the PR BODY carries a blocked term or agent footer; it becomes the squash message body"
fi
if [ -n "$body" ] && printf '%s' "$body" | grep -iqE "$trailer_re"; then
  say "DENY TRAILER: credit trailers go to AUTHORS.md, not the message"
fi
if ! printf '%s' "$title" | grep -qE "^($types)(\([^)]+\))?!?: .+"; then
  say "DENY CONV: the PR title is not a conventional header of the allowed types ($types)"
fi
if [ "${#title}" -gt "$header_max" ]; then
  say "DENY CONV: the PR title exceeds header_max ($header_max): ${#title} chars"
fi

while IFS=$'\t' read -r sha msg aemail cemail; do
  has_term "$msg" && say "DENY MSG: commit ${sha:0:8} carries a blocked term"
  printf '%s' "$msg" | grep -iqE "$trailer_re" && say "DENY TRAILER: commit ${sha:0:8} carries a credit trailer"
  head_line="$(printf '%s' "$msg" | head -1)"
  printf '%s' "$head_line" | grep -qE "^($types)(\([^)]+\))?!?: ." || say "DENY CONV: commit ${sha:0:8} header is not conventional: $head_line"
  printf '%s' "$aemail" | grep -iqE "$allowed_emails" || say "DENY ID: commit ${sha:0:8} author email is not in the allowlist: $aemail"
  printf '%s' "$cemail" | grep -iqE "$allowed_emails" || say "DENY ID: commit ${sha:0:8} committer email is not in the allowlist: $cemail"
done < <(printf '%s' "$commits_json" | jq -r '.[] | [.sha, (.commit.message | gsub("\t"; " ")), (.commit.author.email // ""), (.commit.committer.email // "")] | @tsv')

if [ "$violations" -gt 0 ]; then
  say "policy-guard: $violations violation(s) - the merge stays blocked"
  cat >&2 << 'REPAIR'
cómo corregir (el commit quiere cumplir, y el camino es este):
  - fallo en el título o el cuerpo de la PR: edita la PR
    (gh pr edit N --title/--body) quitando las líneas marcadas arriba;
    el evento edited re-ejecuta esta guardia y re-abre el merge.
  - fallo en el mensaje de un commit (lo dice el SHA): en tu rama,
      git rebase -i $(git merge-base HEAD origin/main)   # `reword` en el commit
      git push --force-with-lease
  - fallo de identidad: corrige el correo del commit
      git rebase -i $(git merge-base HEAD origin/main) --exec 'git commit --amend --reset-author --no-edit'
      git push --force-with-lease
    y deja que git-control elija la identidad en el futuro.
REPAIR
  exit 1
fi
printf 'policy-guard: ok - the squash message and every commit satisfy the policy\n' >&2
